(** ** The lap *)

Lemma lap_1RB1LC_1RC0RD_1LA0LB_0LC0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
