  - destruct (lapi_1RB1LC_1RC0RD_1LA0LB_0LC0RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1RC0RD_1LA0LB_0LC0RD B0_1RB1LC_1RC0RD_1LA0LB_0LC0RD B1_1RB1LC_1RC0RD_1LA0LB_0LC0RD 4 8 p j' [] []).
    + exact run_ovf_1RB1LC_1RC0RD_1LA0LB_0LC0RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1RC0RD_1LA0LB_0LC0RD p j' E).
    + exact (geo_1RB1LC_1RC0RD_1LA0LB_0LC0RD p j' E).
    + lia.
Qed.

