Lemma fireo_1RB1LD_0LC0RB_1LA0RD_1LC0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_0LC0RB_1LA0RD_1LC0LB = Some t ->
