    apply (lap_of_run tm Cc true true cho_1RB1LD_0LC0RB_1LA0RD_1LC0RC B0_1RB1LD_0LC0RB_1LA0RD_1LC0RC B1_1RB1LD_0LC0RB_1LA0RD_1LC0RC 6 10 p j' [] []).
